class Solution {
    public:long long minOperations(vector<int>& a,int k) {
        multiset<int> lo,hi;
        long long sl=0,sh=0,ans=LLONG_MAX;
        auto rebalance=[&]() {
            while((int)lo.size()>(k+1)/2) {
                int x=*lo.rbegin();
                lo.erase(prev(lo.end()));
                sl-=x;
                hi.insert(x);
                sh+=x;
            }
            while((int)lo.size()<(k+1)/2 && !hi.empty()) {
                int x=*hi.begin();
                hi.erase(hi.begin());
                sh-=x;
                lo.insert(x);
                sl+=x;
            }
        }
        ;
        auto insert=[&](int x) {
            if(lo.empty()||x<=*lo.rbegin()) {
                lo.insert(x);
                sl+=x;
            }
            else {
                hi.insert(x);
                sh+=x;
            }
            rebalance();
        }
        ;
        auto erase=[&](int x) {
            auto it=lo.find(x);
            if(it!=lo.end()) {
                sl-=x;
                lo.erase(it);
            }
            else {
                it=hi.find(x);
                sh-=x;
                hi.erase(it);
            }
            rebalance();
        }
        ;
        for(int i=0; i<(int)a.size(); i++) {
            insert(a[i]);
            if(i>=k)erase(a[i-k]);
            if(i>=k-1) {
                long long med=*lo.rbegin();
                ans=min(ans,med*(long long)lo.size()-sl+sh-med*(long long)hi.size());
            }
        }
        return ans;
    }
}
